INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind digitale Daten immer in Binärform gespeichert?', 2, '[{"text": "Ja", "correct": true, "because": "Computer nutzen 0 und 1"}, {"text": "Nein", "correct": false, "because": "Binär ist Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Format nutzen digitale Daten meist?', 3, '[{"text": "Binär", "correct": true, "because": "Grundlage der Datenverarbeitung"}, {"text": "Dezimal", "correct": false, "because": "Nur für Anzeige"}, {"text": "Hexadezimal", "correct": false, "because": "Darstellung, nicht Speicherung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften haben digitale Daten?', 5, '[{"text": "Diskret", "correct": true, "because": "Feste Werte"}, {"text": "Reproduzierbar", "correct": true, "because": "Exakte Kopien möglich"}, {"text": "Kontinuierlich", "correct": false, "because": "Das ist analog"}, {"text": "Unveränderlich", "correct": false, "because": "Kann bearbeitet werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Digitale Daten sind bitsbasiert. b) Sie sind immer verschlüsselt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verschlüsselung optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Verarbeitung digitaler Daten?', 4, '[{"text": "Bitfolge", "correct": false, "because": "Grundlage der Daten"}, {"text": "Speicherformat", "correct": false, "because": "Bestimmt Zugriff"}, {"text": "Papierfarbe", "correct": true, "because": "Physisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob digitale Daten analog sein können?', 2, '[{"text": "Nein", "correct": true, "because": "Analog ist kontinuierlich"}, {"text": "Ja", "correct": false, "because": "Digital ist diskret"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches System liegt digitalen Daten zugrunde?', 3, '[{"text": "Binärsystem", "correct": true, "because": "0 und 1"}, {"text": "Dezimalsystem", "correct": false, "because": "Nur Anzeige"}, {"text": "Oktalsystem", "correct": false, "because": "Seltener genutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arten von digitalen Daten gibt es?', 5, '[{"text": "Text", "correct": true, "because": "Buchstaben und Zahlen"}, {"text": "Bilder", "correct": true, "because": "Pixelbasiert"}, {"text": "Wellenformen", "correct": false, "because": "Analog"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Digitale Daten sind bitsweise organisiert. b) Sie brauchen immer Internet. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Internet optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um digitale Daten zu speichern?', 4, '[{"text": "Speichermedium", "correct": false, "because": "Notwendig"}, {"text": "Binärcodierung", "correct": false, "because": "Grundlage"}, {"text": "Tintenstrahldrucker", "correct": true, "because": "Physische Ausgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind digitale Daten immer sichtbar?', 2, '[{"text": "Nein", "correct": true, "because": "Rohdaten oft unsichtbar"}, {"text": "Ja", "correct": false, "because": "Erst durch Interpretation sichtbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Medien speichern digitale Daten?', 4, '[{"text": "Festplatten", "correct": true, "because": "Häufig genutzt"}, {"text": "USB-Sticks", "correct": true, "because": "Portabel"}, {"text": "Papier", "correct": false, "because": "Analog"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass digitale Daten nicht verändert werden können. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Bearbeitung möglich"}, {"text": "Ja", "correct": false, "because": "Veränderbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Arbeit mit digitalen Daten?', 3, '[{"text": "Integrität", "correct": true, "because": "Korrektheit sicherstellen"}, {"text": "Farbdarstellung", "correct": false, "because": "Sekundär"}, {"text": "Papierformat", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Digitale Daten sind diskret. b) Sie sind physisch greifbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Physisch ist das Medium"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten digitale Daten?', 5, '[{"text": "Schnelle Übertragung", "correct": true, "because": "Elektronisch"}, {"text": "Einfache Kopie", "correct": true, "because": "Verlustfrei duplizierbar"}, {"text": "Hohe Lautstärke", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei digitalen Daten unwichtig?', 3, '[{"text": "Speicherformat", "correct": false, "because": "Bestimmt Lesbarkeit"}, {"text": "Bitstruktur", "correct": false, "because": "Grundlage"}, {"text": "Geruch", "correct": true, "because": "Nicht physisch relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Werden digitale Daten nur in der Cloud gespeichert?', 3, '[{"text": "Nein", "correct": true, "because": "Auch lokal möglich"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend Cloud"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob digitale Daten verlustfrei kopiert werden können?', 2, '[{"text": "Ja", "correct": true, "because": "Exakte Reproduktion"}, {"text": "Nein", "correct": false, "because": "Verlustfrei möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist für digitale Daten entscheidend?', 4, '[{"text": "Binäre Darstellung", "correct": true, "because": "Kern der Digitalisierung"}, {"text": "Physische Form", "correct": false, "because": "Nur Medium"}, {"text": "Manuelle Eingabe", "correct": false, "because": "Automatisiert möglich"}]');
